pub fn find_free_sectors(&self) -> Vec<(u64, u64)> {
    let mut free_sectors = Vec::new();
    let mut last_end = self.header.first_usable_lba;

    for (i, partition) in self.iter() {
        let start = partition.starting_lba;
        if start > last_end {
            let free_start = last_end;
            let free_size = start - last_end;
            let aligned_free_start = (free_start + self.align - 1) / self.align * self.align;
            let aligned_free_size = free_size / self.align * self.align;
            if aligned_free_size > 0 {
                free_sectors.push((aligned_free_start, aligned_free_size));
            }
        }
        last_end = partition.ending_lba + 1;
    }

    if last_end < self.header.last_usable_lba {
        let free_start = last_end;
        let free_size = self.header.last_usable_lba + 1 - last_end;
        let aligned_free_start = (free_start + self.align - 1) / self.align * self.align;
        let aligned_free_size = free_size / self.align * self.align;
        if aligned_free_size > 0 {
            free_sectors.push((aligned_free_start, aligned_free_size));
        }
    }

    free_sectors
}

